  "technical_and_design_decisions": [
    "Leverage YARN REST API to negotiate application deployments and configure resource allocation (CPU, memory, queues, priorities) dynamically.",
    "Utilize Spring Boot's native JarLauncher API for ModuleLauncher to eliminate duplicate classloading and archive launcher code.",
    "Implement asynchronous execution in the deployer via Spring's task execution framework to provide fast CLI return and queue deployments as asynchronous YARN tasks.",
    "Automate HDFS asset staging based on application manifests prior to YARN container submission."
  ],
  "assumptions": [
    "A running Apache Hadoop/YARN cluster and HDFS environment are available for integration testing.",
    "The target Java version is Java 17+ as per Spring Framework 6.0 prerequisites.",
    "Development and testing will be performed by a single experienced senior Java developer.",
    "Existing Spring Cloud Deployer core interfaces serve as the base abstraction for the YARN implementation."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Technical Design and Architecture Specification",
      "activity_description": "Define the architecture for YARN deployer integration, async deployment model, HDFS staging workflow, and Spring Boot JarLauncher integration.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Automated HDFS Deployment & Manifest Orchestration (U1)",
      "activity_description": "Implement automated uploading and orchestration of YARN application artifacts to HDFS using manifest metadata during deployment.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "YARN ResourceManager REST API Integration & Grouping (U2)",
      "activity_description": "Develop REST client to negotiate with YARN ResourceManager API for deployment by groups, setting appType=CLOUDDATA and appName metadata.",
      "most_likely_effort": 4.5
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Multiple App Instances & Deployment Properties Support (U3)",
      "activity_description": "Parse and apply deployment properties (module.*.yarn.app.name, CPU, memory, queues, priority) to configure distinct YARN application instances.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Asynchronous Deployer Execution & Task Queueing (U4)",
      "activity_description": "Refactor deployer operations to run asynchronously so the shell returns immediately while queuing deployments as background tasks in YARN.",
      "most_likely_effort": 3.5
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "ModuleLauncher Refactoring & External JAR Resolution (U5, U6, U8)",
      "activity_description": "Refactor ModuleLauncher to use Spring Boot JarLauncher API, and implement uniform mechanism for resolving and adding external dependency JARs.",
      "most_likely_effort": 5.0
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Testing, Integration, and Documentation (U7)",
      "activity_description": "Create unit and integration test suites for YARN deployment and classloader behaviors, and author technical reference documentation for external JAR handling.",
      "most_likely_effort": 4.0
    }
  ],
  "reported_total": {
    "most_likely_effort": 28.0
  }
}
